public class METSalesOrderHeaderDualWriteUpdate extends METDEVBatchMultipleThreadBase implements BatchRetryable
{
    Integer            numOfRecords;

    DialogField        dlgNumOfRecords;

    PositiveNumber      maxTaskCount;
    DialogField         dlgMaxTaskCount;

    QueryRun       queryRun;

    #define.CurrentVersion(2)
    #localmacro.CurrentList
        numOfRecords,
        maxTaskCount,
        batchIdentifier
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase       dialog = super();
    ;
    dlgNumOfRecords       = dialog.addFieldValue(extendedtypestr(Integer), numOfRecords, "Number of records", "Number of open records that is ready to sync");
    dlgNumOfRecords.enabled(false);

    dialog.addGroup("Performance settings");
    dlgMaxTaskCount     = dialog.addFieldValue(extendedtypestr(PositiveNumber), maxTaskCount, "Number of batch tasks", "Max number of tasks to create in batch job");

    return dialog;
}

public boolean getFromDialog()
{
    maxTaskCount = dlgMaxTaskCount.value();

    return super();
}

public void initQuery()
{
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tablenum(METSalesTable));
    QueryBuildRange         qBR;
    ;
    qBR = SysQuery::findOrCreateRange(qbds, fieldnum(METSalesTable, DualWriteRequired));
    qBR.value(queryValue(NoYes::Yes));
    qBR.status(RangeStatus::Locked);

    queryRun = new QueryRun(query);
}

public void calcNumOfRecords()
{
    numOfRecords = SysQuery::countTotal(new QueryRun(queryRun.query()));
}

public boolean unpack(container _packedClass)
{
    Version    version = RunBase::getVersion(_packedClass);
    container  queryCon;
    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList, queryCon] = _packedClass;
            if (SysQuery::isPackedOk(queryCon))
            {
                queryRun = new QueryRun(queryCon);
            }
            else
            {
                this.initQuery();
            }
            break;
        case 1:
            [version, numOfRecords, queryCon] = _packedClass;
            if (SysQuery::isPackedOk(queryCon))
            {
                queryRun = new QueryRun(queryCon);
            }
            else
            {
                this.initQuery();
            }
            break;
        default:
            return false;
    }
    return true;
}

public void runStartTask()
{
    info(strFmt("METSalesOrderHeaderDualWriteUpdate - Start operation. %1 record(s) to process", numOfRecords));
}

public void runThreadTask()
{
    int                     processedCounter;
    METSalesTable           metSalesTable, metSalesTableUpdate;
    QueryBuildDataSource    qbds = queryRun.query().dataSourceTable(tablenum(METSalesTable));

    qbds.addRange(fieldnum(METSalesTable, RecId)).value(batchIdentifier);

    while (queryRun.next())
    {
        metSalesTable = queryRun.get(tablenum(METSalesTable));

        try
        {
            ttsbegin;

            metSalesTableUpdate = METSalesTable::findRecId(metSalesTable.RecId, true);

            if (metSalesTableUpdate && metSalesTableUpdate.DualWriteRequired == NoYes::Yes)
            {
                metSalesTableUpdate.DualWriteRequired = NoYes::No;
                metSalesTableUpdate.update();
            }

            ttscommit;

            processedCounter++;
        }
        catch (Exception::Error)
        {
            error(strFmt("METSalesOrderHeaderDualWriteUpdate: failed to update DualWriteRequired for SalesId %1 (RecId %2)", metSalesTable.SalesId, metSalesTable.RecId));
        }
        catch (Exception::Deadlock)
        {
            error(strFmt("METSalesOrderHeaderDualWriteUpdate: deadlock while updating SalesId %1 (RecId %2)", metSalesTable.SalesId, metSalesTable.RecId));
        }
        catch (Exception::UpdateConflict)
        {
            error(strFmt("METSalesOrderHeaderDualWriteUpdate: update conflict while updating SalesId %1 (RecId %2)", metSalesTable.SalesId, metSalesTable.RecId));
        }
    }

    info(strFmt("METSalesOrderHeaderDualWriteUpdate: %1 record(s) processed for range %2", processedCounter, batchIdentifier));
}

public void runFinalTask()
{
    int remaining;

    remaining = SysQuery::countTotal(queryRun);

    info(strFmt("METSalesOrderHeaderDualWriteUpdate - All threads complete. %1 record(s) still pending DualWriteRequired update", remaining));
}

public container getBatchIdentifiersRangeCon()
{
    container  res;
    QueryRun   queryRunLocal = new QueryRun(queryRun.query());

    QueryBuildDataSource   qBDS = queryRunLocal.query().dataSourceTable(tablenum(METSalesTable));
    int                    totalRecords, curRecord, recordsPerBatch;
    RecId                  fromRecId, toRecId;

    qBDS.sortClear();
    qBDS.addSortField(fieldnum(METSalesTable, RecId));

    totalRecords = SysQuery::countTotal(queryRunLocal);
    recordsPerBatch = maxTaskCount > 0 ? totalRecords div maxTaskCount : totalRecords;
    if (! recordsPerBatch)
    {
        recordsPerBatch = 1;
    }

    while (queryRunLocal.next())
    {
        METSalesTable   metSalesTable = queryRunLocal.get(tablenum(METSalesTable));
        if (! fromRecId)
        {
            fromRecId = metSalesTable.RecId;
        }
        curRecord++;
        toRecId = metSalesTable.RecId;
        if ((curRecord mod recordsPerBatch) == 0)
        {
            res += SysQuery::range(fromRecId, toRecId);
            fromRecId = 0;
            curRecord = 0;
        }
    }
    if (curRecord && fromRecId && toRecId)
    {
        res += SysQuery::range(fromRecId, toRecId);
    }

    return res;
}

public static METSalesOrderHeaderDualWriteUpdate construct()
{
    return new METSalesOrderHeaderDualWriteUpdate();
}

static ClassDescription description()
{
    return "Dual write sales order header updates";
}

public static void main(Args _args)
{
    METSalesOrderHeaderDualWriteUpdate    runObject = METSalesOrderHeaderDualWriteUpdate::construct();
    ;
    if (runObject.prompt())
    {
        runObject.runOperation();
    }
}
